async function sendMessage(){if(message.sending)return;if(!message.text.trim()&&!message.files.length){notify('先写一句话，或添加附件');return;}message.sending=true;const snapshot={text:message.text,files:[...message.files],objectIds:[...message.objectIds],version:message.version};message.feedback='正在保存原输入…';syncMessage();try{for(const f of snapshot.files)if(!f.asset){const r=await api('/api/uploads',{name:f.name,data:await base64(f.file),mime:f.file.type||'application/octet-stream'});f.asset=r.asset;}const attempt=message.attempt?.version===snapshot.version?message.attempt:{version:snapshot.version,requestId:uid()};message.attempt=attempt;const result=await api('/api/messages',{text:snapshot.text,objectIds:snapshot.objectIds,attachments:snapshot.files.map(f=>f.asset.id),requestId:attempt.requestId});recordUpsert(result.record);if(message.text===snapshot.text){message.text='';const input=$('#message-text');if(input&&input.value===snapshot.text)input.value='';}message.files=message.files.filter(f=>!snapshot.files.includes(f));for(const f of snapshot.files)if(f.preview)URL.revokeObjectURL(f.preview);message.attempt=null;message.feedback='原输入已保存，正在提交秘书整理。';persistDrafts();syncMessage();renderAttachments();renderMessageHistory();try{const job=await runSecretary(result.record.id);message.feedback=jobFeedback(job);}catch(e){message.feedback='原输入已保存；整理尚未启动：'+e.message;const record=app.records.find(r=>r.id===result.record.id);record._submitError=e.message;}renderMessageHistory();}catch(e){message.feedback='原输入未确认保存：'+e.message+'。文字和附件仍保留，可重试。';}finally{message.sending=false;syncMessage();}}
