function renderMessageHistory(){
 const list=$('#message-history');if(!list)return;
 list.replaceChildren(node('h3',{},'最近留言与回执'));
 if(!app.records.length){list.append(node('p',{class:'muted small'},'尚无留言。'));return;}
 for(const r of app.records.slice(0,30)){
  const record=node('article',{class:'message-record'},node('div',{class:'message-record-head'},`${r.actor?.name||'我'} · ${displayTime(r.at)}`),node('div',{class:'message-bubble'},r.text||'（附件）'));
  if(r.attachments?.length)record.append(node('div',{class:'record-assets'},r.attachments.map(a=>{
   const url=safeURL(a.url);return url?node('a',{href:url,target:'_blank',rel:'noopener noreferrer'},a.name||'附件'):node('span',{},a.name||'附件');
  })));
  for(const receipt of [...(r.receipts||[])].reverse())record.append(node('div',{class:'receipt'},node('div',{class:'receipt-head'},`AI秘书 · ${displayTime(receipt.at)} · ${({completed:'整理已结束',failed:'整理未完成',running:'处理进展',queued:'已排队'})[receipt.status]||'处理回执'}`),node('p',{},receipt.text||readable(receipt.receipt)||'暂无文字回执'),receipt.objectIds?.length?recordObjectLinks(receipt.objectIds):null));
  // Generated notebook records are already secretary output, not fresh human input.
  if(r.actor?.kind&&r.actor.kind!=='human'){
   if(r.objectIds?.length)record.append(recordObjectLinks(r.objectIds));
   record.append(node('p',{class:'processing'},'秘书追加记录'));list.append(record);continue;
  }
  const job=[...app.jobs.values()].filter(j=>j.messageId===r.id).at(-1);
  const processing=job?.status||r.processing||'pending';
  const stage=jobStageText(job?.stage);
  const statusText=processing==='completed'?(r.receipts?.length?'整理已结束':'整理已结束，暂无文字回执'):processing==='failed'?`整理失败：${job?.error||r._submitError||'请查看处理回执'}`:processing==='running'?`秘书整理中${stage?' · '+stage:''}`:job?'整理排队中':'原输入已保存，尚未启动整理';
  record.append(node('p',{class:`processing ${processing==='failed'?'failed':''}`},statusText));
  if(processing==='failed'||!job&&processing!=='completed')record.append(button('重试整理','retry-secretary',{onclick:async e=>{
   e.target.disabled=true;try{await runSecretary(r.id);r._submitError='';renderMessageHistory();}catch(error){notify(error.message);e.target.disabled=false;}
  }}));
  list.append(record);
 }
}
function startPolling(){
 if(pollTimer)return;
 pollTimer=setInterval(async()=>{
  if(pollBusy)return;
  const pending=[...app.jobs.values()].filter(j=>['queued','running'].includes(j.status));
  if(!pending.length){clearInterval(pollTimer);pollTimer=null;return;}
  pollBusy=true;
  try{
   let complete=false;
   for(const j of pending){
    try{
     const r=await api(`/api/jobs/${encodeURIComponent(j.id)}`);
     const current=app.jobs.get(j.id);
     if(['completed','failed'].includes(current?.status)&&['queued','running'].includes(r.job.status))continue;
     app.jobs.set(j.id,{...j,...r.job});
     if(message.currentJobId===j.id){message.feedback=jobFeedback(r.job);syncMessage();}
     if(['completed','failed'].includes(r.job.status))complete=true;
    }catch{/* Keep saved input and retry the read on the next poll. */}
   }
   if(complete){try{const data=await api('/api/messages');app.records=data.records||app.records;await reload(true);}catch{}}
   renderMessageHistory();
  }finally{pollBusy=false;}
 },900);
}
