document.addEventListener('keydown',e=>{
 if(e.key!=='Enter')return;
 const target=e.target instanceof Element?e.target:null;if(!target)return;if(target.closest('.schedule-root,.schedule-dialog,.tool-details'))return;
 const choice=target.closest('button.state-choice,button[data-review-preset]');
 // These focused controls confirm the already-selected draft. Suppress their
 // native Enter activation too, so holding Enter cannot toggle a reminder.
 if(e.isComposing||e.keyCode===229||e.repeat||e.shiftKey||e.altKey){if(choice)e.preventDefault();return;}
 if(target.closest('#message-panel')){
  if((e.metaKey||e.ctrlKey)&&target.id==='message-text'){e.preventDefault();sendMessage();}
  return;
 }
 if(e.metaKey||e.ctrlKey){if(choice)e.preventDefault();return;}
 if(choice){
  e.preventDefault();e.stopPropagation();
  const id=choice.closest('[data-editor-for]')?.dataset.editorFor;
  if(id&&!choice.disabled)saveTask(id,'confirm');
  return;
 }
 if(target.closest('button,a,select,input,.quote-box,form'))return;
 if(target.closest('#detail-panel')){
  if(app.detailId){e.preventDefault();saveTask(app.detailId,'confirm');}
  return;
 }
 const row=target.closest('.task-row');
 if(app.view==='review'&&row){e.preventDefault();saveTask(row.dataset.taskId,'confirm');}
});
